{\small
\resumeSubHeadingListStart

\resumeSubheading
  {Machine Learning Engineer Intern}{May 2025 -- August 2025}
  {Ayar Labs}{Santa Clara, CA}
  \resumeItemListStart
    \resumeItem{Engineered modular services that design scalable, testable code for photonic test measurement ingestion and quality-metric reporting, using clean architecture patterns and REST APIs to reduce average endpoint response time from 2.4s to 1.1s.}
    \resumeItem{Mapped and optimized SQL queries, relational databases to support wafer-level optical transceiver characterization workflows, leveraging PostgreSQL query optimization and targeted indexing to cut wafer summary report runtime from 18 minutes to 3 minutes.}
    \resumeItem{Improved debugging sessions by tracing failures across application logic and database interactions, using SQL EXPLAIN, query plan analysis, and logging/monitoring to identify root cause in one session and eliminate recurring dash.}
