  {Software Engineer Intern}{January 2024 -- June 2024}
  {National Institute of Technology, Jaipur}{Jaipur, India}
  \resumeItemListStart
    \resumeItem{Implemented 7 React and TypeScript web application features, enabling interactive filtering and end-to-end data flow; reduced build time from 21 minutes to 8 minutes by optimizing the software pipeline.}
