    \resumeItem{Strengthened Java codebase by refactoring legacy data-access into reusable modules using OOP design patterns, improving scalability and testability without changing external behavior; cut memory footprint by 26MB.}
  \resumeItemListEnd

\resumeSubheading
  {Software Engineer Intern}{May 2023 -- December 2023}
  {Indian Institute of Technology, Indore}{Indore, India}
  \resumeItemListStart
    \resumeItem{Streamlined debugging by discover, reproduce, and fix programming bugs through unit testing, correcting boundary-condition handling in a Python data parser and reducing failing test cases from 12 to 0 in the affected module.}
    \resumeItem{Discovered reliability gaps by monitoring behavior via logs/alerts, implementing structured logging with ELK to triage ingestion anomalies faster and improving mean time to identify issues by 35\% during integration testing.}
    \resumeItem{Programmed scalable components to handle growth in usage and data volume by building RESTful services with caching, using Redis to serve cached responses for 70\% of repeated requests during peak load testing.}
  \resumeItemListEnd

\resumeSubHeadingListEnd

